insert into public.institutions (name, abbreviation, state, city) values ('Universidade do Oeste Paulista / Hospital Regional de Presidente Prudente', 'UNOESTE/HRPP', 'SP', 'Presidente Prudente')
on conflict (abbreviation) do update set name = excluded.name, state = excluded.state, city = excluded.city;

insert into public.exams (institution_id, name, total_questions)
select id, 'R1 Acesso Direto', 100 from public.institutions where abbreviation = 'UNOESTE/HRPP'
on conflict (institution_id, name) do update set total_questions = excluded.total_questions;

